script.text:

function load$CheckingReport$(g) {
	g._$k = [];
	g._$i = g._getColumnOrder('stt_rec');
	g._$t = g._getColumnOrder('&MultiPrint.Grid.Tag;');
	g._$f = 'keys';
	g.add_commandEvent(on$GridReport$ExecuteCommand);
}
/* <flatten type="Javascript"> */
function dispose$CheckingReport$(g) {
	g._$k = g._$i = g._$t = g._$f = null;
	try {g.remove_commandEvent(on$GridReport$ExecuteCommand);} catch (ex) {}
}
function scatter$GridReport$(g) {
	fill$Grid(g, true);

	if (g._rowCount > 0) {
		g._activeRow = g._rowCount;
		g._activeColumn = g._$t;
		g._activeCell = g._getItem(g._activeRow, g._activeColumn);
	}

}
function on$GridReport$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender,	b = sender.get_id();;
	switch (action) {
		case 'SyncCRM':
				if (!isCheck$Grid(g)) break;
				var f = g._language == "v" ? "Hệ thống sẽ gửi các chứng từ đang được chọn, bạn có chắc chắn thực hiện không?": "The selected transaction will be forwarded to bank-hub system, are you sure to continue?";
				$message.show(f, 0, String.format("postData($find('{0}'));", b), String.format("$find('{0}')._focusWhenTabChanged();", b))
			break;
		default:
			break;
	}
}

function postData(g, force) {
			var id = g.get_id();

			if (!force) {
				g._busy(true);
				$func.showWait(id);
				window.setTimeout(function() {postData(g, true);}, 2);
				return;
			}

			var query = {df: g._$df, dt: g._$dt, lst_stt_rec: g._$k.toString(), ma_ct: 'PT1'}

			console.log('g', query);

			Fox.PostData('../AppHandler/ApiCaller.ashx', 'PostCashReceipt'
										, query
										, function (res) { onRequest$Completed(res, id); }
										, function (res) { onRequest$Failed(res, id); }
									);
}

/*
function isCheck$Grid(a) {
		var b = a.get_id(), limitedInvoice = 100,
		d = a._language == "v" ? "Chưa có bản ghi nào được chọn, phải đánh dấu trước khi thực hiện chức năng này.": "No record selected, please select at least one record to process.",
		c = a._language == "v" ? String.format('Mỗi lần chỉ được phép gửi tối đa <span class="Highlight">{0}</span> chứng từ.', limitedInvoice) : String.format('Limit exceeded error, maximum number of voucher is <span class="Highlight">{0}</span>.', limitedInvoice);
		if (a._$k.length == 0) {
				$message.show(d, String.format("$find('{0}')._focusWhenTabChanged();", b));
				return false
		}
		if (a._$k.length > limitedInvoice) {
				$message.show(c, String.format("$find('{0}')._focusWhenTabChanged();", b));
				return false
		}
		return true
}
*/

function onRequest$Completed(r, id) {
	var g = $find(id);
console.log('response', r);
	var m =  r.messages;
	var err = null;
	if (r.code != 200) {
			m = g._language == 'v'? 'Đồng bộ thất bại' : 'Update fail';
			err = r.messages;
	}
	$func.hideWait(id);
	g._busy(false);
	//$message.show(m, 'var f = $find("'+ id +'"); f.closeDialog();', null, null, err);	 
	$message.show(m, null, null, null, err);	 
	return;
}

function onRequest$Failed(r, id) {
	var g = $find(id);
console.log('response', r);
	var err = g._language == 'v'? 'Đồng bộ thất bại' : 'Update fail';			
	$func.hideWait(id);
	g._busy(false);
	$message.show(err, null, null, null, r.messages);	 
	return
}
/* </flatten> */
			&JavascriptReportInit;
			&ScriptTagReport;
			&PrintRightScript;

query.text:
&DeclareCommandFilter;

insert into #filter select '_sync_crm', 0, N'(((((((ÿ_sync_crm != 1)))))))'
if @s5 != 0 insert into #filter select 's5', 0, N'(((((((ÿs5 = ' + rtrim(@s5) + ')))))))'
